base = {"kafka_brokers": 3, "eks_version": "1.31", "mirror_to_hub": True}
regions = {"au": {"aws_region": "ap-southeast-2", "tz": "Australia/Sydney"},
           "eu": {"aws_region": "eu-central-1", "tz": "Europe/Berlin", "kafka_brokers": 6}}
for name, over in regions.items():
    print(name, {**base, **over})
# au {'kafka_brokers': 3, 'eks_version': '1.31', 'mirror_to_hub': True, 'aws_region': 'ap-southeast-2', 'tz': 'Australia/Sydney'}
# eu {'kafka_brokers': 6, 'eks_version': '1.31', 'mirror_to_hub': True, 'aws_region': 'eu-central-1', 'tz': 'Europe/Berlin'}

events = [
    {"op": "c", "after": {"id": 1, "status": "OPEN"}, "lsn": 10},
    {"op": "u", "after": {"id": 1, "status": "PAID"}, "lsn": 11},
    {"op": "c", "after": {"id": 2, "status": "OPEN"}, "lsn": 12},
    {"op": "d", "before": {"id": 2, "status": "OPEN"}, "lsn": 13},
]
def apply(table, ev):
    key = (ev.get("after") or ev.get("before"))["id"]
    cur = table.get(key)
    if cur and cur["lsn"] >= ev["lsn"]:
        return  # 이미 반영한 변경
    if ev["op"] == "d":
        table[key] = {"deleted": True, "lsn": ev["lsn"]}
    else:
        table[key] = {**ev["after"], "lsn": ev["lsn"]}
t = {}
for ev in events: apply(t, ev)
print("한 번:", t)
for ev in events: apply(t, ev)
print("두 번:", t)
# 한 번: {1: {'id': 1, 'status': 'PAID', 'lsn': 11}, 2: {'deleted': True, 'lsn': 13}}
# 두 번: {1: {'id': 1, 'status': 'PAID', 'lsn': 11}, 2: {'deleted': True, 'lsn': 13}}
